import {PERIODS,months,coverage,intervals,comparison,scorecard} from './engine.js';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=(n,d=2)=>n==null?'N/D':Number(n).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const money=c=>c==null?'N/D':(c/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const pct=n=>n==null?'N/D':`${nf(n)}%`;
const signed=n=>n==null?'N/D':`${n>0?'+':''}${nf(n)}%`;
const month=m=>m?new Date(`${m}-02T12:00:00`).toLocaleDateString('pt-BR',{month:'short',year:'numeric'}).replace('.',''):'N/D';
const shortMonth=m=>m?`${m.slice(5)}/${m.slice(0,4)}`:'N/D';
const icons={sound:'<path d="M11 5 6 9H3v6h3l5 4V5Zm4 3a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',music:'<path d="M9 18V5l12-2v13M9 8l12-2"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="16" r="3"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M5 16v5h14v-5"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',swap:'<path d="M3 7h18l-4-4M21 17H3l4 4"/>',screen:'<rect x="3" y="4" width="18" height="14" rx="2"/><path d="M8 22h8m-4-4v4"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};
const icon=n=>`<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.info}</svg>`;
let data,result;
const prefs=(()=>{try{return JSON.parse(localStorage.getItem('embate-preferences')||'{}')}catch{return {}}})();
const state={city:'SP',a:{id:'lula3',start:'2023-01',end:'2026-07'},b:{id:'bolsonaro',start:'2019-01',end:'2022-12'},duration:'equal',index:'inpc',tab:'score',chart:'share',view:'arena',fx:prefs.fx??true,music:prefs.music??true,volume:prefs.volume??16,started:!((prefs.fx??true)||(prefs.music??true))};
function savePrefs(){try{localStorage.setItem('embate-preferences',JSON.stringify({fx:state.fx,music:state.music,volume:state.volume}))}catch{}}
let ctx,musicTimer,step=0;
function audioContext(){ctx??=new (window.AudioContext||window.webkitAudioContext)();if(ctx.state==='suspended')ctx.resume();return ctx;}
function tone(freq,duration=.09,amp=.035,type='square'){
 try{const c=audioContext(),o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.value=freq;
 g.gain.setValueAtTime(0,c.currentTime);g.gain.linearRampToValueAtTime(amp*state.volume/30,c.currentTime+.008);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+duration);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+duration+.02);}catch{}
}
function fx(){if(state.fx){tone(440,.07);setTimeout(()=>tone(660,.11),65);}}
function noise(duration=.035,amp=.008){
 try{const c=audioContext(),length=Math.max(1,Math.floor(c.sampleRate*duration)),buffer=c.createBuffer(1,length,c.sampleRate),samples=buffer.getChannelData(0);for(let i=0;i<length;i++)samples[i]=Math.random()*2-1;
  const source=c.createBufferSource(),filter=c.createBiquadFilter(),gain=c.createGain();source.buffer=buffer;filter.type='highpass';filter.frequency.value=6500;gain.gain.setValueAtTime(amp*state.volume/30,c.currentTime);gain.gain.exponentialRampToValueAtTime(.0001,c.currentTime+duration);source.connect(filter);filter.connect(gain);gain.connect(c.destination);source.start();}catch{}
}
function startMusic(){
 clearInterval(musicTimer);if(!state.music)return;
 const melody=[
  76,null,79,81,83,81,79,76,74,null,76,79,81,79,76,74,72,null,76,79,84,83,79,76,74,76,79,83,86,83,81,79,
  79,null,81,83,86,83,81,79,76,null,79,81,84,81,79,76,74,null,76,79,81,84,83,81,79,76,79,83,88,86,83,81,
  76,79,84,null,83,81,79,76,74,76,79,null,81,83,84,86,88,86,84,83,81,79,76,74,76,null,79,83,81,79,76,74,
  72,null,76,79,81,79,76,74,71,74,76,null,79,81,83,79,76,79,83,86,88,86,83,81,79,76,74,76,79,83,81,79
 ];
 const bass=[40,40,43,43,38,38,35,35,45,45,40,40,43,38,35,40];
 const chords=[[52,55,59],[55,59,62],[50,54,57],[47,50,54],[57,60,64],[52,55,59],[55,59,62],[52,57,60]];audioContext();step=0;
 musicTimer=setInterval(()=>{const note=melody[step%melody.length],bar=Math.floor(step/16)%chords.length;if(note)tone(440*2**((note-69)/12),.105,.0085,'square');if(step%2===0){const arp=chords[bar][Math.floor(step/2)%3];tone(440*2**((arp-69)/12),.09,.0045,'square');noise(.025,.0035);}if(step%4===0)tone(440*2**((bass[Math.floor(step/8)%bass.length]-69)/12),.22,.0105,'triangle');step++;},118);
}

function player(k,i){
 const a=result.analyses[i],w=a.window,s=a.summary;
 return `<section class="player player-${k}" aria-label="Período ${k.toUpperCase()}">
 <div class="player-top"><span class="pixel">PLAYER 0${i+1}</span><span class="corner-code">${k.toUpperCase()}</span></div>
 <label class="select-label" for="period-${k}">ESCOLHA UM GOVERNO</label>
 <select id="period-${k}" data-period="${k}">${PERIODS.map(p=>`<option value="${p.id}" ${state[k].id===p.id?'selected':''}>${p.name} · ${p.start.slice(0,4)}–${p.end.slice(0,4)}</option>`).join('')}<option value="custom" ${state[k].id==='custom'?'selected':''}>Período personalizado</option></select>
 ${state[k].id==='custom'?`<div class="custom-dates"><label>De<input type="month" min="1995-01" max="2026-07" value="${state[k].start}" data-date="${k}:start"></label><label>Até<input type="month" min="1995-01" max="2026-07" value="${state[k].end}" data-date="${k}:end"></label></div>`:''}
 <div class="fighter-intro"><div class="fighter-name"><span class="term">${esc(w.term)}</span><h2>${esc(w.name)}</h2><p>${esc(w.full)}</p></div>${w.portrait?`<figure class="fighter-portrait"><img src="${w.portrait}" alt="Retrato oficial de ${esc(w.full)}"><figcaption>FOTO OFICIAL</figcaption></figure>`:''}</div>
 <div class="window-date">${month(w.start)} até ${month(w.end)} <span>${w.months.length} meses</span></div>
 <div class="player-score"><span class="eyebrow">SALÁRIO COMPROMETIDO COM A CESTA</span><div class="score-number">${s?nf(s.share,1):'N/D'}${s?'<span>%</span>':''}</div><p>${s?'média mensal do período':'Histórico insuficiente para a média'}</p></div>
 <div class="life-meter" aria-label="${s?`${pct(s.share)} do salário comprometido`:'Sem média disponível'}"><span style="width:${s?Math.min(100,s.share):0}%"></span></div>
 <div class="player-mini"><div><strong>${s?nf(s.baskets):'N/D'}</strong><span>cestas por salário</span></div><div><strong>${s?nf(s.hours,0):'N/D'}<small>${s?' h':''}</small></strong><span>horas por cesta</span></div></div>
 <div class="coverage-badge ${a.coverage.complete?'complete':'partial'}"><span>${a.coverage.complete?'✓':'!'}</span> ${a.coverage.count}/${a.coverage.total} meses com dados ${a.coverage.complete?'':'· média indisponível'}</div>
 </section>`;
}
function map(){
 const dates=[...new Set(result.ws.flatMap(w=>w.months))];
 return `<div class="map-stage"><div class="stage-top"><span class="pixel">SELECIONE O CENÁRIO</span><span class="stage-counter">${state.city==='BR'?'BRASIL':state.city==='MACAE'?'RJ':state.city}</span></div>
 <div class="map-wrap"><span class="map-coord coord-one">05° N</span><span class="map-coord coord-two">34° S</span><span class="map-caption">ATLÂNTICO SUL</span>
 <svg class="brazil-map" viewBox="0 0 590 585" role="group" aria-label="Mapa dos estados do Brasil. Selecione um estado para consultar sua capital.">
 ${data.states.map(s=>{const l=data.locations.find(l=>l.id===s.uf),c=coverage(l,dates),status=!l?'unloaded':c.complete?'full':c.count?'partial':'empty';return `<g tabindex="0" role="button" data-city="${s.uf}" aria-label="${esc(s.name)}: ${esc(s.capital)}. ${!l?'Base ainda não recebida':`${c.count} de ${c.total} meses disponíveis`}" aria-pressed="${state.city===s.uf}" class="map-state ${status} ${state.city===s.uf?'selected':''}"><title>${esc(s.name)} · ${esc(s.capital)}\n${!l?'Base ainda não recebida':`${c.count}/${c.total} meses nesta comparação`}</title><path d="${s.path}"/><text x="${s.label[0]}" y="${s.label[1]}" text-anchor="middle">${s.uf}</text></g>`}).join('')}
 </svg></div><div class="map-legend"><span><i class="full"></i>Completo</span><span><i class="partial"></i>Parcial</span><span><i class="empty"></i>Sem dados no recorte</span></div>
 <label class="sr-only" for="city-select">Capital ou município</label><select id="city-select"><option value="BR" ${state.city==='BR'?'selected':''}>Brasil · média das capitais da amostra</option><optgroup label="Capitais">${[...data.states].sort((a,b)=>a.capital.localeCompare(b.capital,'pt-BR')).map(s=>`<option value="${s.uf}" ${state.city===s.uf?'selected':''}>${s.capital} · ${s.uf}${data.locations.some(l=>l.id===s.uf)?'':' · base pendente'}</option>`).join('')}</optgroup><optgroup label="Município adicional"><option value="MACAE" ${state.city==='MACAE'?'selected':''}>Macaé · RJ</option></optgroup></select>
 <p class="map-note">${state.city==='BR'?`${result.sample.length} capitais com todos os meses nas duas janelas.`:state.city==='MACAE'?'Dados do município de Macaé, separados da capital.':'O estado seleciona a capital pesquisada, não a média estadual.'}</p></div>`;
}

function comparisonNotice(){
 const {location:l,analyses:as,sample}=result;
 const notices=[];
 if(!l){notices.push(state.city==='BR'?'Nenhuma amostra completa para as duas janelas. Escolha outros períodos.':`A base de ${data.states.find(s=>s.uf===state.city)?.capital||'esta cidade'} ainda não foi recebida. Os indicadores nacionais continuam disponíveis.`);}
 else if(as.some(a=>!a.coverage.complete)){
  notices.push(`Histórico incompleto em ${l.name}. As médias da cesta só aparecem quando todos os meses da janela estão disponíveis. Explore os registros na linha do tempo ou escolha um período personalizado.`);
 }
 if(l&&!l.sample&&l.id==='RR')notices.push(`Boa Vista: ${l.count} meses pesquisados no arquivo, com grandes intervalos sem registros. A referência recalculada de dez/2015 fica separada dos meses observados.`);
 if(as.some(a=>a.methodBreak))notices.push('Este recorte atravessa a mudança metodológica do DIEESE em 2016. A evolução mostra os valores publicados e a quebra de método deve ser considerada.');
 if(as.some(a=>a.audit.length))notices.push('Há uma divergência entre total e componentes em um registro deste recorte. O total publicado foi preservado; veja Cobertura.');
 if(state.city==='BR'&&sample.length)notices.push(`Amostra fixa: ${sample.map(l=>l.name).join(', ')}. Média simples das capitais selecionadas, não estimativa oficial nacional.`);
 if(state.a.id===state.b.id&&state.a.id!=='custom')notices.push('Você selecionou o mesmo governo nos dois lados. Troque uma seleção para comparar períodos diferentes.');
 return notices.map(t=>`<div class="notice">${icon('info')}<p>${esc(t)}</p></div>`).join('');
}
function score(){
 const [a,b]=result.analyses;
 const board=scorecard(result),names={a:a.window.name,b:b.window.name};
 const outcome=board.overall==='na'?'Placar indisponível por falta de cobertura':board.overall==='tie'?'Empate neste recorte':`${names[board.overall]} venceu este recorte`;
 const explain=board.valid?`${board.valid} critérios independentes entram no placar. Cada rodada vale 1 ponto.`:'Escolha janelas com dados completos para abrir o placar.';
 return `<div class="section-heading score-heading"><div><span class="eyebrow">PLACAR / ${esc(locationName())}</span><h2>Três rodadas, ponto a ponto.</h2></div></div>
 <div class="insight">${icon('info')}<p>${esc(explain)}</p></div>
 <div class="round-grid">${board.rounds.map((r,i)=>roundCard(r,i,a,b)).join('')}</div>
 <div class="power-details"><div><span>Cestas por salário</span><strong class="a-color">A · ${nf(a.summary?.baskets)}</strong><strong class="b-color">B · ${nf(b.summary?.baskets)}</strong></div><div><span>Horas para comprar a cesta</span><strong class="a-color">A · ${a.summary?nf(a.summary.hours,1)+' h':'N/D'}</strong><strong class="b-color">B · ${b.summary?nf(b.summary.hours,1)+' h':'N/D'}</strong></div><p>Cestas, horas e percentual comprometido descrevem a mesma relação matemática; por isso formam uma única rodada.</p></div>
 <div class="salary-panel"><div class="section-heading"><div><span class="eyebrow">DETALHE / INFLAÇÃO</span><h2>Subiu no papel. E no bolso?</h2></div><span class="pill">${state.index.toUpperCase()} · nacional</span></div>
 <p class="section-description">O ganho real compara o aumento do salário com a inflação do mesmo intervalo.</p>
 <div class="inflation-duel">${[a,b].map((r,i)=>{const side=i?'b':'a',round=board.rounds.find(x=>x.id==='real');return `<div class="inflation-side side-${i} ${roundClass(round.winner,side)}"><div class="mini-heading"><span class="player-tag">${i?'B':'A'}</span><strong>${r.window.name}</strong><small>${r.economic?month(r.economic.baseline)+' → '+month(r.economic.last):'Referência indisponível'}</small></div><div class="equation"><div><span>Salário nominal</span><strong>${signed(r.economic?.nominal)}</strong></div><b>vs</b><div><span>Inflação ${state.index.toUpperCase()}</span><strong>${signed(r.economic?.inflation)}</strong></div><b>=</b><div class="real-result"><span>Ganho real</span><strong>${signed(r.economic?.real)}</strong></div></div><p>${r.economic?`O poder de compra geral ${r.economic.real>=0?'cresceu':'caiu'} ${pct(Math.abs(r.economic.real))} nesta janela.`:'Dados insuficientes para o intervalo.'}</p></div>`}).join('')}</div>
 <p class="footnote">A divisão é feita entre os fatores: (1 + aumento salarial) ÷ (1 + inflação) − 1. O salário federal e a inflação nacional são iguais para todas as cidades. Isso não mede apenas alimentação.</p></div>
 ${finalResult(a,b,board,outcome)}
 <div class="score-bottom"><div><strong>Quer abrir a cesta?</strong><p>Veja quanto arroz, carne e outros alimentos pesaram em cada período.</p></div><button class="secondary" data-tab="foods">RAIO-X DOS ALIMENTOS ${icon('arrow')}</button></div>`;
}
function roundClass(winner,side){return winner==='tie'?'tie':winner==='na'?'unavailable':winner===side?'winner':'loser';}
function overallSide(side,r,board){const status=roundClass(board.overall,side),points=board.points[side];return `<div class="overall-side ${side} ${status}">${r.window.portrait?`<img src="${r.window.portrait}" alt="">`:''}<div><span>PLAYER ${side==='a'?'A':'B'}</span><strong>${esc(r.window.name)}</strong><small>${points} ${points===1?'CAMPO CONQUISTADO':'CAMPOS CONQUISTADOS'}</small><em>${status==='winner'?'VENCEDOR DO EMBATE':status==='loser'?'DUELO ENCERRADO':status==='tie'?'EMPATE':'SEM PLACAR'}</em></div></div>`;}
function finalResult(a,b,board,outcome){const aControl=board.valid?50+25*(board.points.a-board.points.b)/board.valid:50;return `<section class="final-reveal ${board.overall==='na'?'unavailable':board.overall}" aria-label="Resultado final do embate"><div class="final-heading"><div><span class="eyebrow">RESULTADO FINAL / ${esc(locationName())}</span><h2>${esc(outcome)}</h2></div><p>O campo avança conforme os rounds conquistados.</p></div><div class="territory-result" style="--a-control:${aControl}%;--b-control:${100-aControl}%">${overallSide('a',a,board)}${overallSide('b',b,board)}<div class="match-center"><span class="pixel">PLACAR FINAL</span><strong>${board.points.a}<i>×</i>${board.points.b}</strong><small>${board.overall==='tie'?'EMPATE':board.overall==='na'?'SEM DADOS':'CAMPO DOMINADO'}</small></div></div></section>`;}
function roundValue(r,side){const value=r[side];if(value==null)return 'N/D';if(r.id==='basket')return pct(value);if(r.id==='real')return signed(value);return `${value>0?'+':''}${nf(value)} pp`;}
function roundExplanation(id){return {basket:'Mede a parcela média do salário mínimo necessária para comprar a cesta básica. Menor é melhor porque a alimentação consumiu uma parte menor da renda.',real:'Compara o reajuste do salário mínimo com a inflação escolhida. Maior é melhor: um resultado positivo indica ganho de poder de compra, enquanto um resultado negativo indica perda.',trend:'Compara quanto o peso da cesta no salário mudou do primeiro ao último mês. Menor é melhor porque uma queda, ou uma alta menor, indica que a cesta passou a comprometer menos renda. Um valor negativo representa melhora.'}[id]||'Este indicador compara os dois períodos selecionados.';}
function roundCard(r,i,a,b){const duelClass=r.winner==='a'?'a-wins':r.winner==='b'?'b-wins':r.winner,helpId=`round-help-${i}`;return `<article class="round-card"><div class="round-title"><span class="pixel">ROUND ${String(i+1).padStart(2,'0')}</span><div><h3>${r.label}</h3><p>${r.help}</p></div><span class="control-help round-help"><button class="control-info" type="button" aria-label="Entender o indicador ${esc(r.label)}" aria-describedby="${helpId}">?</button><span class="control-tooltip" id="${helpId}" role="tooltip"><strong>Como ler este indicador?</strong>${roundExplanation(r.id)}</span></span></div><div class="round-duel ${duelClass}"><div class="round-side a ${roundClass(r.winner,'a')}"><span>A · ${esc(a.window.name)}</span><strong>${roundValue(r,'a')}</strong><small>${r.winner==='a'?'VENCEU O ROUND · +1':r.winner==='tie'?'EMPATE':r.winner==='na'?'SEM DADOS':'ROUND PERDIDO'}</small></div><b>VS</b><div class="round-side b ${roundClass(r.winner,'b')}"><span>B · ${esc(b.window.name)}</span><strong>${roundValue(r,'b')}</strong><small>${r.winner==='b'?'VENCEU O ROUND · +1':r.winner==='tie'?'EMPATE':r.winner==='na'?'SEM DADOS':'ROUND PERDIDO'}</small></div></div></article>`;}
function locationName(){return result.location?.name||data.states.find(s=>s.uf===state.city)?.capital||'Média das capitais';}

function foods(){
 const [a,b]=result.analyses;
 return `<div class="section-heading"><div><span class="eyebrow">RAIO-X / CESTA BÁSICA</span><h2>Cada alimento tem seu peso.</h2></div><span class="subtle">Média do gasto como % do salário</span></div><p class="section-description">As barras mostram quanto da renda foi consumido pela quantidade mensal de cada alimento. Quanto maior a barra, maior a parcela do salário comprometida. Em cada cartão, os dois períodos usam a mesma escala.</p>
 <div class="foods-grid">${data.products.map((name,i)=>{
  const va=a.summary?.foods[i],vb=b.summary?.foods[i];const max=Math.max(1,Math.ceil(Math.max(va||0,vb||0)));
  const na=result.location&&(a.summary||b.summary)&&va==null&&vb==null;
  return `<article class="food-card"><div class="food-title"><span class="food-index">${String(i+1).padStart(2,'0')}</span><h3>${name}</h3><span class="food-unit">% do salário</span></div>${[va,vb].map((v,j)=>`<div class="food-row ${j?'b':'a'}-color"><span class="player-tag">${j?'B':'A'}</span><div class="food-meter"><span style="width:${v!=null?100*v/max:0}%"></span></div><strong>${pct(v)}</strong></div>`).join('')}<p>${na?(state.city==='BR'?'Composição regional diferente; agregado do item indisponível.':'Não integra a cesta desta região.'):`Escala deste alimento: 0–${nf(max,0)}%. ${va==null||vb==null?'Há período sem cobertura completa.':''}`}</p></article>`;
 }).join('')}</div><p class="footnote">Valores de gasto mensal, não preço por kg. Quantidades e tipos de alimento variam por região. Batata não integra as cestas da região 2 do DIEESE.</p>`;
}

function evolution(){
 const [a,b]=result.analyses,key=state.chart;
 const all=[...a.series,...b.series].map(r=>r[key]).filter(v=>v!=null).map(v=>key==='realSalary'?v/100:v);
 const top=all.length?Math.ceil(Math.max(...all)/(key==='share'?10:200))*(key==='share'?10:200):100;
 const yMax=Math.max(top,key==='share'?10:200),W=1060,H=330,L=65,R=24,T=24,B=45;
 const n=Math.max(a.series.length,b.series.length,1),x=i=>L+(n===1?.5:i/(n-1))*(W-L-R),y=v=>H-B-v/yMax*(H-T-B);
 function line(series,cls){let path='',pen=false;const dots=[];series.forEach((r,i)=>{let v=r[key];if(v==null){pen=false;return;}if(key==='realSalary')v/=100;path+=`${pen?'L':'M'}${x(i).toFixed(1)},${y(v).toFixed(1)} `;pen=true;dots.push(`<circle cx="${x(i)}" cy="${y(v)}" r="3.4"><title>${month(r.month)}: ${key==='share'?pct(v):money(v*100)}</title></circle>`);});return `<g class="series-${cls}"><path d="${path}"/>${dots.join('')}</g>`;}
 return `<div class="section-heading"><div><span class="eyebrow">HISTÓRICO / MÊS A MÊS</span><h2>Veja a trajetória completa.</h2></div><label class="chart-filter"><span>Indicador</span><select id="chart-select"><option value="share" ${key==='share'?'selected':''}>Parcela do salário para a cesta</option><option value="realSalary" ${key==='realSalary'?'selected':''}>Salário real em R$ de jul/2026</option></select></label></div>
 <div class="chart-legend"><span class="a-color"><i></i>${a.window.name} · ${month(a.window.start)}</span><span class="b-color"><i></i>${b.window.name} · ${month(b.window.start)}</span></div>
 <div class="chart-frame"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${key==='share'?'Percentual do salário comprometido pela cesta':'Salário real corrigido pela inflação'} por mês de cada período. Os dados também estão disponíveis na tabela abaixo.">
 ${Array.from({length:6},(_,i)=>{const v=yMax*i/5;return `<line x1="${L}" y1="${y(v)}" x2="${W-R}" y2="${y(v)}" class="grid-line"/><text x="${L-12}" y="${y(v)+5}" text-anchor="end">${nf(v,0)}${key==='share'?'%':''}</text>`}).join('')}
 ${Array.from(new Set([0,...Array.from({length:Math.floor(n/12)},(_,i)=>(i+1)*12-1),n-1])).map(i=>`<text x="${x(i)}" y="${H-15}" text-anchor="middle">Mês ${i+1}</text>`).join('')}${line(a.series,'a')}${line(b.series,'b')}</svg></div>
 <p class="footnote">As linhas começam no primeiro mês de cada janela. Lacunas permanecem sem ligação. ${key==='realSalary'?`Salário nacional corrigido pelo ${state.index.toUpperCase()}, em dinheiro de julho/2026.`:'Os valores são os publicados na pesquisa; a mudança metodológica de 2016 está sinalizada quando cruza o recorte.'}</p>
 <details class="data-table"><summary>Consultar os dados mensais ${icon('arrow')}</summary><div class="table-scroll"><table><thead><tr><th>Mês A</th><th>Cesta A</th><th>% do salário A</th><th>Mês B</th><th>Cesta B</th><th>% do salário B</th></tr></thead><tbody>${Array.from({length:n},(_,i)=>{const r=a.series[i],s=b.series[i];return `<tr><td>${shortMonth(r?.month)}</td><td>${money(r?.basket)}</td><td>${pct(r?.share)}</td><td>${shortMonth(s?.month)}</td><td>${money(s?.basket)}</td><td>${pct(s?.share)}</td></tr>`}).join('')}</tbody></table></div></details>`;
}
function coverageView(){
 const dates=months('1995-01',data.lastMonth);
 const missing=data.states.filter(s=>!data.locations.some(l=>l.id===s.uf));
 const short=data.locations.filter(l=>l.capital&&l.count<dates.length/2).sort((a,b)=>a.count-b.count);
 const sort=[...data.states].sort((a,b)=>a.capital.localeCompare(b.capital,'pt-BR')).map(s=>({id:s.uf,name:s.capital,uf:s.uf}));sort.push({id:'MACAE',name:'Macaé',uf:'RJ'});
 return `<div class="section-heading"><div><span class="eyebrow">BASE / TRANSPARÊNCIA</span><h2>O que temos. E o que falta.</h2></div><span class="pill">${data.locations.filter(l=>l.capital).length}/27 capitais + Macaé</span></div>
 <div class="coverage-summary"><div><strong>${data.locations.reduce((s,l)=>s+l.count,0).toLocaleString('pt-BR')}</strong><span>observações mensais</span></div><div><strong>${month(data.lastMonth)}</strong><span>última competência da base</span></div><div><strong>${missing.length} capitais</strong><span>aguardando planilha</span></div></div>
 <div class="notice success">${icon('info')}<p>${missing.length?`Ainda faltam: ${missing.map(s=>`${s.capital} (${s.uf})`).join(', ')}.`:'Mapa completo: as 27 capitais foram incorporadas.'} Macaé permanece como município adicional e não substitui a capital Rio de Janeiro.</p></div>
 <div class="notice warning">${icon('info')}<p>Séries com pouca cobertura: ${short.map(l=>`${l.name} (${l.count} meses)`).join(', ')}. Boa Vista é especialmente fragmentada; meses vazios continuam vazios e não entram em médias incompletas.</p></div>
 <div class="coverage-key"><span><i></i>Mês com dados</span><span>Os espaços vazios são meses sem registro. Escala: jan/1995 → jul/2026.</span></div>
 <div class="coverage-list">${sort.map(s=>{const l=data.locations.find(l=>l.id===s.id),groups=l?intervals(l):[];return `<article class="coverage-row ${state.city===s.id?'active':''}"><div class="city-heading"><button data-city="${s.id}"><strong>${s.name}</strong><span>${s.uf}${s.id==='MACAE'?' · município':''}</span></button><span class="${l?'':'pending'}">${l?`${l.count} / ${dates.length} meses`:'Base pendente'}</span></div><div class="coverage-strip" role="img" aria-label="${s.name}: ${l?l.count:0} meses com dados entre janeiro de 1995 e julho de 2026">${dates.map(m=>`<i class="${l?.rows[m]?'present':''}" title="${month(m)} · ${l?.rows[m]?'com dados':'sem registro'}"></i>`).join('')}</div><p>${l?groups.map(([a,b])=>a===b?month(a):`${month(a)}–${month(b)}`).join(' · '):'Envie a exportação desta capital para incluí-la na ferramenta.'}${s.id==='RR'?' · Atenção: histórico muito fragmentado.':''}</p>${l?.audit.length?`<p class="audit-note">Conferência: total e soma dos componentes diferem em ${l.audit.map(x=>`${month(x.month)} (${money(x.sumDifferenceCents)})`).join(', ')}. Preservamos os valores publicados.</p>`:''}</article>`}).join('')}</div>
 <div class="sources-panel"><h3>Fontes dos dados</h3><div class="source-grid"><a href="${data.sources.basket}" target="_blank" rel="noopener">DIEESE / Conab<span>Cesta e alimentos · exportações fornecidas</span>${icon('arrow')}</a><a href="${data.sources.salary}" target="_blank" rel="noopener">Ipeadata<span>Salário mínimo vigente · MTE12_SALMIN12</span>${icon('arrow')}</a><a href="${data.sources.inpc}" target="_blank" rel="noopener">IBGE via Banco Central<span>INPC 188 · IPCA 433</span>${icon('arrow')}</a><a href="${data.sources.map}" target="_blank" rel="noopener">IBGE<span>Malha dos estados · mapa simplificado</span>${icon('arrow')}</a></div><p class="footnote">Base preparada em 07/09/2026. As séries são versionadas; o site não consulta novas divulgações automaticamente.</p></div>`;
}
function methodology(){return `<dialog id="method-dialog" aria-labelledby="method-title"><div class="dialog-top"><span class="eyebrow">MANUAL DA ARENA</span><button class="icon-btn" id="close-method" aria-label="Fechar metodologia">${icon('close')}</button></div><h2 id="method-title">Como a comparação funciona</h2>
 <details open><summary>Como funciona o placar</summary><p>Há três rodadas independentes: menor parcela média do salário comprometida pela cesta; maior ganho real do salário; e menor mudança, em pontos percentuais, no peso da cesta entre o primeiro e o último mês. Cada rodada válida vale um ponto.</p><p>Cestas por salário, horas de trabalho e percentual comprometido são formas equivalentes de expressar a mesma relação, então contam como uma única rodada. Empates usam tolerância de 0,005 e não dão ponto. “Vencedor do recorte” vale somente para os períodos, local e indicadores escolhidos.</p></details>
 <details><summary>Cesta e salário no mesmo mês</summary><p>Comprometimento = cesta ÷ salário mínimo bruto × 100. Cestas por salário = salário ÷ cesta. Horas = cesta ÷ salário × 220. São indicadores equivalentes a uma jornada mensal de 220 horas, não a jornada de toda pessoa.</p><p>As médias são calculadas sobre os indicadores de cada mês. Não descontamos INSS. Por isso, o percentual pode diferir do divulgado pelo DIEESE sobre salário líquido.</p></details>
 <details><summary>Inflação e ganho real</summary><p><strong>INPC:</strong> acompanha famílias urbanas com renda de 1 a 5 salários mínimos, cuja pessoa de referência é assalariada. Por estar mais próximo da renda de quem depende do salário, é o padrão desta ferramenta.</p><p><strong>IPCA:</strong> acompanha famílias urbanas com renda de 1 a 40 salários mínimos, qualquer que seja a fonte de renda. É a medida oficial de inflação do país e oferece uma visão mais ampla do consumo. <a href="https://www.ibge.gov.br/explica/inflacao.php" target="_blank" rel="noopener">Entenda os índices no IBGE</a>.</p><p>Trocar o índice altera o cálculo de inflação, ganho real e salário corrigido, mas não altera o preço publicado da cesta. Ambos são produzidos pelo IBGE e obtidos no SGS do Banco Central. O aumento real é calculado dividindo o fator de aumento salarial pelo fator de inflação e subtraindo 1.</p><p>A variação começa no mês anterior à janela e termina no último mês selecionado. O gráfico de salário real traz todos os valores em reais de julho/2026. A proporção cesta/salário não recebe outro desconto de inflação.</p></details>
 <details><summary>Governos, duração e transições</summary><p><strong>Comparação equivalente, recomendada:</strong> identifica o período mais curto e usa os primeiros meses dessa mesma duração nos dois lados. Lula II contra Dilma II, por exemplo, compara os primeiros 16 meses de cada governo. Temer contra Bolsonaro compara os primeiros 31 meses de cada governo. É a opção padrão porque evita dar a um lado mais tempo que ao outro.</p><p><strong>Períodos inteiros:</strong> usa toda a janela disponível de cada lado. Nos mesmos exemplos, seriam 48 contra 16 meses e 31 contra 48 meses. Essa opção serve para conhecer a trajetória total de cada período, mas é menos equilibrada para decidir um vencedor direto.</p><p>Nenhuma opção elimina diferenças de contexto, sazonalidade, crises ou condições herdadas. Lula III termina em julho/2026, último mês com valores nesta base, e aparece como parcial.</p><p>Dilma II termina em abril/2016; Temer começa em junho/2016, incluindo o exercício interino. Maio/2016, mês da transição, fica fora desses resumos e pode ser consultado no recorte personalizado. <a href="https://www.gov.br/secretariageral/pt-br/centrais-de-conteudo/biblioteca-da-pr/galeria-dos-ex-presidentes/dilma-vana-rousseff" target="_blank" rel="noopener">Referência histórica</a>.</p><p>A associação a um governo organiza o tempo. Não comprova que ele causou sozinho o resultado.</p></details>
 <details><summary>Capitais, Macaé e agregado</summary><p>Clicar em um estado consulta a capital pesquisada; não é média estadual. Macaé tem série própria, fora do agregado de capitais.</p><p>“Brasil” significa a média simples de uma amostra fixa de capitais com todos os meses nas duas janelas. A lista aparece no resultado. Não é uma estimativa oficial do custo de vida de todo o país. Os alimentos só são agregados quando integram todas as cestas da amostra.</p></details>
 <details><summary>Meses vazios e revisões</summary><p>Ausência não é zero. Médias com qualquer mês faltante são bloqueadas; a linha do tempo preserva as lacunas. A cobertura mostra os intervalos efetivos de cada arquivo, incluindo Boa Vista.</p><p>Dezembro/2015 recalculado é preservado como referência separada e não contado duas vezes. Os gráficos exibem os níveis publicados, com aviso ao cruzar a mudança de metodologia de 2016. <a href="https://www.dieese.org.br/metodologia/metodologiaCestaBasica2016.pdf" target="_blank" rel="noopener">Metodologia DIEESE</a>.</p><p>Os arquivos também mencionam tomada especial de preços a partir de abril/2020. Divergências maiores que sete centavos entre o total e a soma dos itens aparecem na cobertura; o total publicado é preservado.</p></details>
 <details><summary>Como ler as barras de alimentos</summary><p>Cada barra mede o gasto mensal previsto na cesta como percentual do salário. A escala é igual para A e B dentro de cada alimento e está escrita no cartão. Não são notas ou preços por quilo.</p><p>Quantidades e variedades mudam por região. Batata não faz parte da cesta da região 2. <a href="https://www.dieese.org.br/metodologia/metodologiaCestaBasica2025.pdf" target="_blank" rel="noopener">Composição das cestas</a>.</p></details>
 <details><summary>Créditos dos retratos oficiais</summary><p>As imagens presidenciais são cópias locais otimizadas de arquivos do Wikimedia Commons: <a href="https://commons.wikimedia.org/wiki/File:Fernando_Henrique_Cardoso_(1999)_(cropped).jpg" target="_blank" rel="noopener">FHC / Agência Brasil</a>; <a href="https://commons.wikimedia.org/wiki/File:Foto_oficial_do_primeiro_mandato_do_presidente_Luiz_In%C3%A1cio_Lula_da_Silva_-_53155275756.jpg" target="_blank" rel="noopener">Lula I / Lula Oficial</a>; <a href="https://commons.wikimedia.org/wiki/File:Lula_-_foto_oficial_-_05_jan_2007_(cropped2).jpg" target="_blank" rel="noopener">Lula II / Ricardo Stuckert</a>; <a href="https://commons.wikimedia.org/wiki/File:Dilma_Rousseff_-_foto_oficial_2011-01-09_(cropped2).jpg" target="_blank" rel="noopener">Dilma / Roberto Stuckert Filho</a>; <a href="https://commons.wikimedia.org/wiki/File:Michel_Temer_(foto_oficial).jpg" target="_blank" rel="noopener">Temer / Beto Barata</a>; <a href="https://commons.wikimedia.org/wiki/File:Jair_Bolsonaro_2019_Portrait_(3x4_cropped).jpg" target="_blank" rel="noopener">Bolsonaro / Isac Nóbrega</a>; e <a href="https://commons.wikimedia.org/wiki/File:Foto_oficial_de_Luiz_In%C3%A1cio_Lula_da_Silva_(2023%E2%80%932027).jpg" target="_blank" rel="noopener">Lula III / Palácio do Planalto</a>. Licenças e arquivos originais estão nas páginas vinculadas.</p></details>
 <p class="dialog-footer">Confira o indicador, o período e a cobertura antes de comparar.</p></dialog>`;}

function topbar(){return `<header class="topbar"><button class="wordmark" id="home" aria-label="Voltar à seleção do embate"><span class="brand-monogram">EG</span><span>ARCADE<br><b>ECONÔMICO</b></span></button><div class="header-note">DADOS REAIS <span>×</span> PERSPECTIVAS DIFERENTES</div><div class="sound-controls"><button id="fx-toggle" aria-pressed="${state.fx}" title="Ativar ou desativar efeitos sonoros">${icon('sound')}<span>Efeitos ${state.fx?'ON':'OFF'}</span></button><button id="music-toggle" aria-pressed="${state.music}">${icon('music')}<span>Música ${state.music?'ON':'OFF'}</span></button><label class="volume-label"><span class="sr-only">Volume do áudio</span><input id="volume" type="range" min="0" max="50" value="${state.volume}" aria-label="Volume do áudio"></label></div></header>`;}
function arenaScreen(){const l=result.location,latest=l&&!l.sample?l.rows[l.last]?.[0]:null;const durationText=state.duration==='equal'?`Recorte equilibrado: os dois lados usam os primeiros ${result.ws[0].months.length} meses.`:`Trajetórias inteiras: A usa ${result.ws[0].months.length} meses e B usa ${result.ws[1].months.length} meses.`;return `<main class="screen-page arena-page"><div class="marquee"><span class="marquee-line"></span><div><p class="pixel">O PODER DE COMPRA EM JOGO</p><h1>EMBATE <span>DOS</span> GOVERNOS</h1></div><span class="marquee-line"></span></div>
 <div class="control-deck"><div class="duration-control"><div class="deck-tabs"><span class="deck-label">RECORTE <span class="control-help"><button class="control-info" type="button" aria-label="Explicar as opções de recorte" aria-describedby="duration-help">?</button><span class="control-tooltip" id="duration-help" role="tooltip"><strong>Na prática</strong><b>Comparação equivalente</b> usa nos dois lados a duração do governo mais curto, sempre desde o início. É a opção recomendada para o embate direto. <b>Períodos inteiros</b> usa todos os meses disponíveis e pode colocar durações diferentes frente a frente.</span></span></span><button data-duration="equal" aria-pressed="${state.duration==='equal'}" class="${state.duration==='equal'?'active':''}">Comparação equivalente <small>RECOMENDADO</small></button><button data-duration="full" aria-pressed="${state.duration==='full'}" class="${state.duration==='full'?'active':''}">Períodos inteiros</button></div><p class="duration-live">${durationText}</p></div><div class="deck-right"><span class="control-label"><label for="index-select">INFLAÇÃO</label><span class="control-help inflation-help"><button class="control-info" type="button" aria-label="Explicar a diferença entre INPC e IPCA" aria-describedby="inflation-help">?</button><span class="control-tooltip" id="inflation-help" role="tooltip"><strong>Qual índice escolher?</strong><b>INPC</b> acompanha famílias assalariadas de 1 a 5 salários mínimos e é o padrão do projeto. <b>IPCA</b> cobre famílias de 1 a 40 salários mínimos e é a inflação oficial ampla.</span></span></span><select id="index-select"><option value="inpc" ${state.index==='inpc'?'selected':''}>INPC · renda 1–5 SM</option><option value="ipca" ${state.index==='ipca'?'selected':''}>IPCA · renda 1–40 SM</option></select><button class="method-btn" id="open-method">${icon('info')} Como funciona</button></div></div>
 <div class="cabinet"><div class="cabinet-screw screw-tl"></div><div class="cabinet-screw screw-tr"></div><div class="arena">${player('a',0)}${map()}${player('b',1)}</div><div class="cabinet-controls"><div class="selected-place"><span class="live-square"></span><div><strong>${esc(locationName())}</strong><span>${state.city==='BR'?'Média simples · amostra fixa':latest?`Última cesta: ${money(latest)} · ${month(l.last)}`:'Base aguardando dados'}</span></div></div><div class="battle-buttons"><button class="swap-btn" id="swap" aria-label="Trocar períodos A e B">${icon('swap')}</button><span class="vs pixel">VS</span><button class="arcade-button" id="fight">VER O EMBATE ${icon('arrow')}</button></div><div class="data-cutoff"><span>ÚLTIMO MÊS COM VALORES</span><strong>JULHO / 2026</strong></div></div></div></main>`;}
function resultsScreen(){return `<main class="screen-page results-page"><div class="results-top"><button class="back-button" id="back-arena">← NOVO EMBATE</button><div><span class="pixel">BATALHA ATUAL</span><strong>${esc(result.analyses[0].window.name)} <i>VS</i> ${esc(result.analyses[1].window.name)}</strong><small>${esc(locationName())}</small></div><button class="method-btn" id="open-method">${icon('info')} Como funciona</button></div>
 <div class="result-shell" id="results"><div class="result-tabs" role="tablist" aria-label="Análises">${[['score','01','PLACAR'],['evolution','02','EVOLUÇÃO'],['foods','03','ALIMENTOS'],['coverage','04','COBERTURA']].map(([id,n,label])=>`<button role="tab" id="tab-${id}" aria-controls="analysis-panel" aria-selected="${state.tab===id}" tabindex="${state.tab===id?'0':'-1'}" class="${state.tab===id?'active':''}" data-tab="${id}"><span>${n}</span>${label}</button>`).join('')}<button class="export-btn" id="export" title="Exportar dados desta comparação" aria-label="Baixar CSV da comparação">${icon('download')}<span>CSV</span></button></div><section class="analysis-panel" id="analysis-panel" role="tabpanel" aria-labelledby="tab-${state.tab}">${comparisonNotice()}${state.tab==='score'?score():state.tab==='foods'?foods():state.tab==='evolution'?evolution():coverageView()}</section></div>
 <footer><span class="footer-brand pixel">EMBATE DOS GOVERNOS</span><p>DIEESE / Conab · Ipeadata · IBGE <span>|</span> Fontes e critérios disponíveis na ferramenta.</p><button id="footer-method">Ler metodologia ${icon('arrow')}</button></footer></main>`;}
function startGate(){if(state.started)return '';return `<div class="start-gate" role="dialog" aria-modal="true" aria-labelledby="start-title"><div class="start-panel"><span class="pixel">INSERT COIN</span><h1 id="start-title">Compare o poder de compra entre governos.</h1><p>Escolha dois períodos e uma capital para descobrir quanto a cesta básica pesou no salário, como a inflação afetou o ganho real e quais alimentos consumiram mais renda.</p><button class="arcade-button start-button" id="start-audio">ENTRAR NA ARENA ${icon('arrow')}</button><button class="silent-button" id="start-silent">Entrar sem som</button></div></div>`;}
function render(focusSelector){
 result=comparison(data,state);document.body.dataset.view=state.view;
 $('#app').innerHTML=`${topbar()}${state.view==='arena'?arenaScreen():resultsScreen()}${methodology()}${startGate()}<div class="toast" role="status" id="toast"></div>`;
 bind();if(!state.started)requestAnimationFrame(()=>$('#start-audio')?.focus());else if(focusSelector)document.querySelector(focusSelector)?.focus({preventScroll:true});
}

function bind(){
 document.querySelectorAll('[data-period]').forEach(el=>el.onchange=()=>{state[el.dataset.period].id=el.value;fx();render(`#${el.id}`);});
 document.querySelectorAll('[data-date]').forEach(el=>el.onchange=()=>{const [k,v]=el.dataset.date.split(':');const val=el.value;if(val<'1995-01'||val>data.lastMonth||!val){render(`[data-date="${el.dataset.date}"]`);return;}
  state[k][v]=val;if(state[k].start>state[k].end)state[k][v==='start'?'end':'start']=val;render(`[data-date="${el.dataset.date}"]`);});
 document.querySelectorAll('[data-city]').forEach(el=>{const choose=()=>{state.city=el.dataset.city;fx();render(`[data-city="${state.city}"]`);};el.onclick=choose;if(el.tagName.toLowerCase()==='g')el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();choose();}};});
 if($('#city-select'))$('#city-select').onchange=e=>{state.city=e.target.value;fx();render('#city-select');};
 document.querySelectorAll('[data-duration]').forEach(el=>el.onclick=()=>{state.duration=el.dataset.duration;fx();render(`[data-duration="${state.duration}"]`);});
 if($('#index-select'))$('#index-select').onchange=e=>{state.index=e.target.value;render('#index-select');};
 document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{state.tab=el.dataset.tab;fx();render(`#tab-${state.tab}`);});
 document.querySelectorAll('[role="tab"]').forEach(el=>el.onkeydown=e=>{const tabs=['score','evolution','foods','coverage'];let i=tabs.indexOf(state.tab);if(e.key==='ArrowRight')i=(i+1)%4;else if(e.key==='ArrowLeft')i=(i+3)%4;else if(e.key==='Home')i=0;else if(e.key==='End')i=3;else return;e.preventDefault();state.tab=tabs[i];render(`#tab-${state.tab}`);});
 if($('#swap'))$('#swap').onclick=()=>{[state.a,state.b]=[state.b,state.a];fx();render('#swap');};
 if($('#fight'))$('#fight').onclick=()=>{state.tab='score';state.view='results';fx();render('#back-arena');};
 if($('#back-arena'))$('#back-arena').onclick=()=>{state.view='arena';fx();render('#fight');};
 $('#home').onclick=()=>{state.view='arena';fx();render('#fight');};
 $('#fx-toggle').onclick=()=>{state.fx=!state.fx;state.started=true;if(state.fx){audioContext();fx();}savePrefs();render('#fx-toggle');};
 $('#music-toggle').onclick=()=>{state.music=!state.music;state.started=true;startMusic();savePrefs();render('#music-toggle');};
 $('#volume').oninput=e=>{state.volume=+e.target.value;savePrefs();};
 if($('#start-audio'))$('#start-audio').onclick=()=>{state.started=true;state.fx=true;state.music=true;audioContext();tone(523,.08,.04);setTimeout(()=>tone(659,.08,.04),80);setTimeout(()=>tone(784,.18,.04),160);startMusic();savePrefs();render('#fight');};
 if($('#start-silent'))$('#start-silent').onclick=()=>{state.started=true;state.fx=false;state.music=false;startMusic();savePrefs();render('#fight');};
 let opener;
 const open=e=>{opener=e.currentTarget;$('#method-dialog').showModal();};
 if($('#open-method'))$('#open-method').onclick=open;if($('#footer-method'))$('#footer-method').onclick=open;
 $('#close-method').onclick=()=>$('#method-dialog').close();
 $('#method-dialog').onclose=()=>opener?.focus();
 $('#method-dialog').onclick=e=>{if(e.target.id==='method-dialog'){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
 if($('#chart-select'))$('#chart-select').onchange=e=>{state.chart=e.target.value;render('#chart-select');};
 if($('#export'))$('#export').onclick=exportCSV;
}
function exportCSV(){
 const headers=['Localidade','Tipo de agregado','Capitais da amostra','Periodo','Inicio janela','Fim janela','Mes','Cesta BRL','Salario bruto BRL','Parcela do salario pct','Cestas por salario','Horas equivalentes','Indice inflacao','Salario real BRL jul2026','Status do mes','Fonte cesta','Fonte salario'];
 const rows=[headers];
 result.analyses.forEach((a,i)=>a.series.forEach(r=>rows.push([locationName(),state.city==='BR'?'Media simples de capitais; amostra fixa':'Localidade pesquisada',result.sample.map(l=>l.name).join(' | '),a.window.name,a.window.start,a.window.end,r.month,r.basket==null?'':nf(r.basket/100),nf(r.salary/100),r.share==null?'':nf(r.share),r.baskets==null?'':nf(r.baskets),r.hours==null?'':nf(r.hours),state.index.toUpperCase(),r.realSalary==null?'':nf(r.realSalary/100),r.basket==null?'Sem registro':'Observado',data.sources.basket,data.sources.salary])));
 const csv='\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(';')).join('\r\n');
 const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=`embate-${state.city}-${state.index}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);
 const toast=$('#toast');toast.textContent='Comparação exportada com fontes e meses ausentes.';toast.classList.add('visible');setTimeout(()=>toast.classList.remove('visible'),3500);
}

